package br.com.confirmacao.patient.domain;import br.com.confirmacao.professional.domain.Professional;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="patients",uniqueConstraints=@UniqueConstraint(name="uk_patients_professional_phone",columnNames={"professional_id","phone"})) public class Patient{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="professional_id",nullable=false)private Professional professional;@Column(name="full_name",nullable=false,length=150)private String fullName;@Column(name="birth_date")private LocalDate birthDate;@Column(nullable=false,length=20)private String phone;@Column(length=254)private String email;@Enumerated(EnumType.STRING)@Column(name="preferred_channel",nullable=false,length=20)private PreferredContactChannel preferredChannel;@Enumerated(EnumType.STRING)@Column(name="consent_status",nullable=false,length=20)private ConsentStatus consentStatus;@Column(name="consented_at")private Instant consentedAt;@Column(nullable=false)private boolean active;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected Patient(){}public Patient(Professional p,String n,LocalDate b,String ph,String e,PreferredContactChannel c){if(p==null)throw new IllegalArgumentException("O profissional responsável é obrigatório");id=UUID.randomUUID();professional=p;fullName=name(n);birthDate=birth(b);phone=phone(ph);email=email(e);preferredChannel=c==null?PreferredContactChannel.WHATSAPP:c;consentStatus=ConsentStatus.PENDING;active=true;createdAt=updatedAt=Instant.now();}public void update(String n,LocalDate b,String ph,String e,PreferredContactChannel c){ensureActive();fullName=name(n);birthDate=birth(b);phone=phone(ph);email=email(e);if(c==null)throw new IllegalArgumentException("O canal preferencial é obrigatório");preferredChannel=c;updatedAt=Instant.now();}private String name(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("O nome do paciente é obrigatório");return v.trim();}private LocalDate birth(LocalDate v){if(v!=null&&v.isAfter(LocalDate.now()))throw new IllegalArgumentException("A data de nascimento não pode estar no futuro");return v;}private String phone(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("O telefone do paciente é obrigatório");String n=v.replaceAll("\\D","");if(n.length()<10||n.length()>15)throw new IllegalArgumentException("O telefone do paciente é inválido");return n;}private String email(String v){return v==null||v.isBlank()?null:v.trim().toLowerCase(Locale.ROOT);}public void grantConsent(){ensureActive();consentStatus=ConsentStatus.GRANTED;consentedAt=updatedAt=Instant.now();}public void revokeConsent(){ensureActive();consentStatus=ConsentStatus.REVOKED;consentedAt=null;updatedAt=Instant.now();}private void ensureActive(){if(!active)throw new IllegalArgumentException("Ative o paciente antes de editar dados ou alterar o consentimento");}public void activate(){active=true;updatedAt=Instant.now();}public void deactivate(){active=false;updatedAt=Instant.now();}public UUID getId(){return id;}public Professional getProfessional(){return professional;}public String getFullName(){return fullName;}public LocalDate getBirthDate(){return birthDate;}public String getPhone(){return phone;}public String getEmail(){return email;}public PreferredContactChannel getPreferredChannel(){return preferredChannel;}public ConsentStatus getConsentStatus(){return consentStatus;}public Instant getConsentedAt(){return consentedAt;}public boolean isActive(){return active;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
